+/**
+ * True when [file] is release-irrelevant per a paths-ignore pattern. The
+ * workflow only uses `<dir>/**` forms; a bare pattern must match exactly.
+ */
+function isIgnoredPath(file, patterns) {
+  for (var i = 0; i < patterns.length; i++) {
+    var p = patterns[i];
