+  var ignored = opts.ignored || [];
+  if (opts.releaseCommit && opts.mainHead === opts.releaseCommit) {
+    return { action: 'noop', reason: 'main-already-released', relevantCount: 0 };
+  }
+  if (!opts.releaseCommit) {
