+/** The subset of [files] that demands a release (paths-ignore removed). */
+function filterRelevantFiles(files, patterns) {
+  var relevant = [];
+  for (var i = 0; i < files.length; i++) {
+    if (!isIgnoredPath(files[i], patterns)) relevant.push(files[i]);
+  }
+  return relevant;
+}
+
